#!/usr/bin/env python3
# NOTE: THIS CODE WAS GENERATED BY CLAUDE
"""Parse a Geant4 (MT) log: run config, run summary, warnings, per-track stats."""
import re, sys, csv, statistics as st
from collections import Counter, defaultdict

LEN = {"fm": 1e-12, "nm": 1e-6, "um": 1e-3, "mm": 1.0, "cm": 10.0, "m": 1000.0}  # -> mm
ENE = {"meV": 1e-9, "eV": 1e-6, "keV": 1e-3, "MeV": 1.0, "GeV": 1e3}              # -> MeV

def to_len(s): v, u = s.split(); return float(v) * LEN[u]
def to_mev(s): v, u = s.split(); return float(v) * ENE[u]

PREFIX = re.compile(r"^G4WT(\d+) >\s?")
PAIR = r"(\S+ \S+)\s+"
STEP = re.compile(r"^\s*(\d+)\s+" + PAIR * 7 + r"(\S+)\s+(\S+)\s*$")
HDR = re.compile(r"Particle = (\S+),\s+Track ID = (\d+),\s+Parent ID = (\d+)")

def parse(path):
    lines = open(path, errors="replace").read().splitlines()
    info = {"config": [], "warnings": Counter(), "tracks": []}
    cur = {}        # thread -> track dict being built
    pending = {}    # thread -> (particle, id, parent)
    threads_events = {}

    for i, raw in enumerate(lines):
        m = PREFIX.match(raw)
        thr = int(m.group(1)) if m else None
        line = PREFIX.sub("", raw)

        # --- version / physics list
        if "Geant4 version Name" in line:
            info["version"] = line.strip(" *").replace("Geant4 version Name:", "").strip()
        if line.startswith("<<< Reference Physics List"):
            info["physics_list"] = line.split("List")[1].strip()

        # --- macro config (master only)
        if thr is None and re.match(r"^/(gun|run/beamOn|run/initialize|tracking/verbose)", line):
            info["config"].append(line.strip())

        # --- warnings / exceptions
        mw = re.match(r"\*\*\* G4Exception : (\w+)", line.strip())
        if mw:
            issuer = ""
            for j in range(i + 1, min(i + 4, len(lines))):
                mi = re.search(r"issued by : (.+)", lines[j])
                if mi: issuer = mi.group(1).strip(); break
            info["warnings"][(mw.group(1), issuer)] += 1

        # --- per-thread event counts
        me = re.search(r"\[thread (\d+)\]\s+Number of events processed : (\d+)", line)
        if me: threads_events[int(me.group(1))] = int(me.group(2))

        # --- tracking tables
        mh = HDR.search(line)
        if mh and thr is not None:
            pending[thr] = (mh.group(1), int(mh.group(2)), int(mh.group(3)))
            continue
        ms = STEP.match(line)
        if ms and thr is not None:
            n = int(ms.group(1))
            x, y, z, ke, de, sl, tl = ms.groups()[1:8]
            vol, proc = ms.group(8), ms.group(9)
            if n == 0:
                p = pending.get(thr, ("?", 0, 0))
                cur[thr] = dict(thread=thr, particle=p[0], track_id=p[1], parent=p[2],
                                x0=to_len(x), y0=to_len(y), z0=to_len(z), ke0=to_mev(ke),
                                steps=0, edep=0.0, edep_by_vol=Counter(), procs=Counter(),
                                path_in_solid=0.0)
                info["tracks"].append(cur[thr])
            t = cur.get(thr)
            if t is None: continue
            t["steps"] += 1
            t["edep"] += to_mev(de)
            t["edep_by_vol"][vol] += to_mev(de)
            t["procs"][proc] += 1
            if vol != "World": t["path_in_solid"] += to_len(sl)
            t.update(xf=to_len(x), yf=to_len(y), zf=to_len(z), kef=to_mev(ke),
                     last_vol=vol, last_proc=proc)

    # --- run summary / user summary (whole-text regexes)
    text = "\n".join(PREFIX.sub("", l) for l in lines if not PREFIX.match(l))
    def grab(pat, cast=str):
        m = re.search(pat, text); return cast(m.group(1)) if m else None
    info["run"] = dict(
        events=grab(r"Run Summary\s+Number of events processed : (\d+)", int),
        timing=grab(r"Number of events processed : \d+\s+(User=.*)"),
        description=grab(r"The run is: (.*)"),
        edep=grab(r"Energy deposit:\s+(.*)"),
        eleak=grab(r"Energy leakage:\s+(.*)"),
        niel=grab(r"NIEL energy calculated:\s+(.*)"),
        process_calls=grab(r"Process calls frequency :\s+(.*)"),
        fluence_msg=grab(r"(Target fluence:.*)"),
        required_primaries=grab(r"(=> Required primaries.*)"),
        beamon_suggest=grab(r"Run with: (.*)"),
    )
    info["threads_events"] = threads_events
    return info

def report(info):
    print("=== GEANT4 LOG SUMMARY ===")
    print("Version     :", info.get("version"))
    print("Physics list:", info.get("physics_list"))
    print("Macro cmds  :", " | ".join(info["config"]))
    r = info["run"]
    print("\n--- Run summary ---")
    for k, v in r.items():
        print(f"{k:20s}: {v}")
    te = info["threads_events"]
    print(f"{'events per thread':20s}: {dict(sorted(te.items()))}  (sum={sum(te.values())})")

    tr = info["tracks"]
    prim = [t for t in tr if t["parent"] == 0]
    print(f"\n--- Tracks parsed from tracking-verbose: {len(tr)} ({len(prim)} primaries) ---")
    print("(only events whose tables were printed -- check against event count above)")
    if prim:
        def stat(name, vals, unit):
            print(f"{name:28s} mean={st.mean(vals):.4g} min={min(vals):.4g} "
                  f"max={max(vals):.4g} {unit}")
        stat("Initial KE", [t["ke0"] for t in prim], "MeV")
        stat("Final z (stopping depth)", [t["zf"] * 1e3 for t in prim], "um")
        stat("Path length in solid", [t["path_in_solid"] * 1e3 for t in prim], "um")
        stat("Total Edep (sum dEStep)", [t["edep"] for t in prim], "MeV")
        stat("Steps/track", [t["steps"] for t in prim], "")
        print("Final KE all ~0 (stopped)?", all(t["kef"] < 1e-3 for t in prim))
        print("Last process:", dict(Counter(t["last_proc"] for t in prim)))
        print("Stopping volume:", dict(Counter(t["last_vol"] for t in prim)))
        ev = Counter()
        for t in prim:
            for v, e in t["edep_by_vol"].items(): ev[v] += e
        print("Edep by 'Volume' column (MeV):", {k: round(v, 3) for k, v in ev.items()})
        print("Process counts:", dict(sum((t["procs"] for t in prim), Counter())))

    print("\n--- Warnings / exceptions ---")
    for (code, who), n in info["warnings"].most_common():
        print(f"{n:4d} x {code:10s} {who}")

def write_csv(info, out):
    with open(out, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["thread","particle","id","parent","x0_mm","y0_mm","z0_mm","ke0_MeV",
                    "zf_mm","kef_MeV","edep_MeV","steps","path_in_solid_mm","last_vol","last_proc"])
        for t in info["tracks"]:
            w.writerow([t["thread"],t["particle"],t["track_id"],t["parent"],t["x0"],t["y0"],
                        t["z0"],t["ke0"],t.get("zf"),t.get("kef"),t["edep"],t["steps"],
                        t["path_in_solid"],t.get("last_vol"),t.get("last_proc")])

if __name__ == "__main__":
    if len(sys.argv) < 2:
        sys.exit("usage: read_geant4_output.py logfile [tracks.csv]")
    info = parse(sys.argv[1])
    report(info)
    if len(sys.argv) > 2:
        write_csv(info, sys.argv[2]); print("\nWrote", sys.argv[2])